def lpHaarPrefix (𝕜 : Type*) [RCLike 𝕜] (p : BanachExponent) (hp : p.val ≠ ∞)
    (n : ℕ) (S : Finset (Fin (2 ^ n))) : IntervalLp 𝕜 p →L[𝕜] IntervalLp 𝕜 p :=
  lpHaarDyadicMean 𝕜 p hp n + lpHaarPartialLevel 𝕜 p n S

